qualified_questions.sparql_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?lightProperty
WHERE {
  ?lightProperty rdf:type owl:NamedIndividual ;
                 rdf:type s4envi:LightProperty .
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?definition
WHERE {
  s4envi:Luminiscence rdfs:subClassOf s4envi:LightProperty ;
                      rdfs:comment ?definition .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX om: <http://www.wurvoc.org/vocabularies/om-1.8/>

SELECT ?representation
WHERE {
  om:reciprocal_day rdf:type s4envi:FrequencyUnit ;
                    rdfs:comment ?representation .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX om: <http://www.wurvoc.org/vocabularies/om-1.8/>

SELECT ?property
WHERE {
  ?property rdf:type s4envi:LightProperty ;
            s4envi:hasUnit om:reciprocal_second-time .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX om: <http://www.wurvoc.org/vocabularies/om-1.8/>

SELECT ?lengthProperty
WHERE {
  ?lengthProperty rdf:type s4envi:LengthUnit ;
                  rdfs:subClassOf* s4envi:LengthUnit .
  om:decametre rdf:type ?lengthProperty .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?device ?frequencyMeasurement
WHERE {
  ?device s4envi:hasFrequencyMeasurement ?frequencyMeasurement .
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?object ?color
WHERE {
    ?object s4envi:hasColor ?color .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?sensor ?transmissionPeriod
WHERE {
  ?sensor s4envi:hasTransmissionPeriod ?transmissionPeriod .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?object ?geometry
WHERE {
  ?object s4envi:hasGeometry ?geometry .
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?component
WHERE {
  ?part s4envi:isComponentOf ?component .
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?lightPoint
WHERE {
  ?device s4envi:hasLightPoint ?lightPoint .
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?container
WHERE {
  ?container s4envi:contains ?specificObject .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?container
WHERE {
  ?object s4envi:isContainedIn ?container .
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?definition
WHERE {
  s4envi:CommunicationInterface rdfs:isDefinedBy ?definition
}

SELECT ?definition
WHERE {
  s4envi:DigitalRepresentation rdfs:comment ?definition .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?property
WHERE {
  ?property a saref:Property .
  FILTER NOT EXISTS {
    ?property owl:disjointWith saref:Measurement .
    ?property owl:disjointWith saref:Service .
  }
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?compassDirection ?color ?light
WHERE {
  ?compassDirection rdf:type s4envi:CompassDirection .
  ?color rdf:type s4envi:Color .
  ?light rdf:type s4envi:Light .
  FILTER NOT EXISTS { ?compassDirection owl:disjointWith ?color }
  FILTER NOT EXISTS { ?compassDirection owl:disjointWith ?light }
  FILTER NOT EXISTS { ?color owl:disjointWith ?light }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?measurementType
WHERE {
  ?measurementType rdfs:subClassOf* saref:Measurement .
  FILTER NOT EXISTS {
    ?measurementType owl:disjointWith s4envi:CommunicationProtocol .
  }
  FILTER NOT EXISTS {
    ?measurementType owl:disjointWith s4envi:DigitalRepresentation .
  }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT DISTINCT ?unitOfMeasure
WHERE {
  ?unitOfMeasure a saref:UnitOfMeasure .
  FILTER NOT EXISTS { 
    ?unitOfMeasure rdfs:subClassOf* s4envi:Color .
  }
  FILTER NOT EXISTS { 
    ?unitOfMeasure rdfs:subClassOf* s4envi:CompassDirection .
  }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?service
WHERE {
  ?service a saref:Service .
  FILTER NOT EXISTS {
    ?service owl:disjointWith ?measurement ;
             owl:disjointWith ?property ;
             owl:disjointWith ?communicationInterface .
  }
  FILTER(?measurement = saref:Measurement || ?property = saref:Property || ?communicationInterface = s4envi:CommunicationInterface)
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?communicationProtocol
WHERE {
  ?communicationProtocol a s4envi:CommunicationProtocol .
  FILTER NOT EXISTS {
    ?communicationProtocol owl:disjointWith s4envi:Geometry .
  }
  FILTER NOT EXISTS {
    ?communicationProtocol owl:disjointWith s4envi:DigitalRepresentation .
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?creator
WHERE {
  ?ontology dcterms:creator ?creator .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?title
WHERE {
  [] dcterms:title ?title
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?issued
WHERE {
  ?ontology dcterms:issued ?issued .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?license
WHERE {
  ?ontology dcterms:license ?license .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX vann: <http://purl.org/vocab/vann/>

SELECT ?preferredNamespaceUri
WHERE {
  ?ontology vann:preferredNamespaceUri ?preferredNamespaceUri .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?contributor
WHERE {
  [] dcterms:contributor ?contributor .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?publisher
WHERE {
  ?ontology dcterms:publisher ?publisher
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX vann: <http://purl.org/vocab/vann/>

SELECT (COUNT(?ontology) AS ?count) ?title
WHERE {
  ?ontology vann:preferredNamespacePrefix ?prefix ;
            dcterms:title ?title .
}
GROUP BY ?prefix ?title
HAVING (COUNT(?ontology) > 1)

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX vann: <http://purl.org/vocab/vann/>

SELECT ?ontology1 ?ontology2
WHERE {
  ?ontology1 dcterms:creator ?creator ;
             vann:preferredNamespaceUri ?namespaceUri .
  ?ontology2 dcterms:creator ?creator ;
             vann:preferredNamespaceUri ?namespaceUri .
  FILTER(?ontology1 != ?ontology2)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?source
WHERE {
  ?ontology dcterms:source ?source .
}

SELECT ?versionIRI
WHERE {
  <https://saref.etsi.org/saref4envi/> owl:versionIRI ?versionIRI .
}

# Write your query here.
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?creator ?contributor (GROUP_CONCAT(DISTINCT ?otherOntology; separator=", ") AS ?otherContributions)
WHERE {
  <https://saref.etsi.org/saref4envi/> dcterms:creator ?creator .
  <https://saref.etsi.org/saref4envi/> dcterms:contributor ?contributor .
  OPTIONAL {
    ?otherOntology dcterms:creator|dcterms:contributor ?creator ;
                   rdf:type owl:Ontology .
    FILTER(?otherOntology != <https://saref.etsi.org/saref4envi/>)
  }
  OPTIONAL {
    ?otherOntology dcterms:creator|dcterms:contributor ?contributor ;
                   rdf:type owl:Ontology .
    FILTER(?otherOntology != <https://saref.etsi.org/saref4envi/>)
  }
}
GROUP BY ?creator ?contributor

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX saref4envi: <https://saref.etsi.org/saref4envi/>

SELECT ?versionIRI ?changeDescription
WHERE {
  saref4envi: rdf:type owl:Ontology ;
              owl:versionIRI ?versionIRI .
  OPTIONAL { saref4envi: dcterms:description ?changeDescription . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?importedOntology ?specificParts
WHERE {
  <https://saref.etsi.org/saref4envi/> owl:imports ?importedOntology .
  OPTIONAL {
    <https://saref.etsi.org/saref4envi/> owl:imports <https://saref.etsi.org/core/v3.2.1/> .
    <https://saref.etsi.org/core/v3.2.1/> ?property ?specificParts .
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?license ?otherOntology ?otherLicense
WHERE {
  <https://saref.etsi.org/saref4envi/> dcterms:license ?license .
  OPTIONAL {
    ?otherOntology rdf:type owl:Ontology ;
                   dcterms:subject "environment" ;
                   dcterms:license ?otherLicense .
    FILTER(?otherOntology != <https://saref.etsi.org/saref4envi/>)
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?relation
WHERE {
  {
    <https://saref.etsi.org/saref4envi/> dcterms:creator <http://purl.org/net/mpoveda> .
    BIND("Creator" AS ?relation)
  }
  UNION
  {
    <https://saref.etsi.org/saref4envi/> dcterms:contributor <http://purl.org/net/mpoveda> .
    BIND("Contributor" AS ?relation)
  }
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?lightPoint
WHERE {
  ?lightPoint rdf:type s4envi:LightPoint ;
              wgs84:location ?location .
}
